use xiom.io;
use xiom.string;
interface Validator {
  fn validate(self) -> Bool;
  fn error_message() -> Str;
}

type Age = {
  years: Int;
}

fn Age.validate(self) -> Bool {
  return self.years >= 13;
}

fn Age.error_message(self) -> Str {
  return "Must be 13 or older";
}

type Email = {
  address: Str;
}

fn Email.validate(self) -> Bool {
  return string.str_index_of(self.address, "@") != None and string.str_index_of(self.address, ".") != None;
}

fn Email.error_message(self) -> Str {
  return "Must contain @ and .";
}

fn check_field[T: Validator](field: &T) {
  if field.validate() {
    io.println("OK");
  } else {
    io.println("ERROR: " + field.error_message());
  }
}

fn main() -> Int {
  let age = Age{ years: 15 };
  let email = Email{ address: "bad_email" };

  check_field(&age);
  check_field(&email);
  return 0;
}
